insert into public.products (id, name, sub, cat, price, variants, sku, blurb, image, in_stock, sort)
values
  ('bcond', 'Batana Conditioner', '250ml', 'Batana', 99, null, 'RT-BCN', 'Our carefully formulated Batana Conditioner targets hair growth and overall health with a potent blend of natural ingredients, leaving your hair silky and nourishing.', '/products/batana-conditioner.png', true, 1),
  ('bmask', 'Batana Hair Mask', '125ml', 'Batana', 135, null, 'RT-BHM', 'Infused with the prized batana oil, nourishing sheabutter, and strengthening castor oil. This intensive hair mask is your ultimate treatment for deep repair. It works to restore elasticity, reduce split ends and seal in moisture, leaving your hair feeling incredibly strong, soft and visibly healthier from the first use.', '/products/batana-hair-mask.png', true, 2),
  ('bhf', 'Batana Hairfood', '125ml jar', 'Batana', 149, null, 'RT-BHF', 'Nourish your hair from root to tip with our ultra-rich hair food. Crafted with pure Batana oil and strengthening Black castor oil. This formula deeply moisturises and protects strands. A luxurious blend of sheabutter, coconut oil and sweet almond oil seals in hydration, while rosemary oil invigorates the scalp. The result is stronger, softer and healthier hair with natural shine.', '/products/batana-hairfood.png', true, 3),
  ('bo', 'Batana Oil', '50ml / 100ml', 'Batana', 149, '[{"label":"50ml","price":149},{"label":"100ml","price":250}]'::jsonb, 'RT-BO', 'Nourish your hair with this potent oil blend designed for growth and strength. Crafted with pure Batana oil and black castor oil, this deeply conditions and fortifies strands from the root. The lightweight grapeseed oil ensures a non-greasy finish, while invigorating rosemary oil stimulates the scalp, leaving your hair feeling healthy, soft and vibrant.', '/products/batana-oil.png', true, 4),
  ('bsh', 'Batana Shampoo', '250ml', 'Batana', 99, null, 'RT-BSH', 'Growth-focused shampoo, crafted with natural ingredients for silky, nourished hair.', '/products/batana-shampoo.png', true, 5),
  ('ehgo', 'Extreme Hairgrower Oil', '100ml', 'Hair Growth', 149, null, 'RT-EHGO', 'A herbal blend oil crafted to stimulate hair follicles and open pores. A powerhouse of the best herbs such as rosemary, moringa and peppermint to soothe the scalp and encourage extreme hair growth.', '/products/extreme-hairgrower-oil.png', true, 6),
  ('ehlr', 'Extreme Hairloss Recovery', 'treatment', 'Hair Growth', 630, null, 'RT-EHLR', 'Baldness, alopecia… this Extreme Hairloss Recovery is designed to reverse the devastating hair loss. This set has Hairloss Solution 30ml, Hair Tonic 100ml, Extreme Hairgrower Oil 30ml, and Sheabutter Hair Food. Applied daily, new hair will start growing from 3 weeks.', '', true, 7),
  ('hgc', 'Hair Growth Conditioner', '250ml', 'Hair Growth', 85, null, 'RT-HGC', 'Our hair growth conditioner is enriched with natural ingredients to leave your hair silky and nourished. Our carefully formulated conditioner supports healthy hair growth and strengthens your strands with a potent mix of natural ingredients.', '/products/hair-growth-conditioner.png', true, 8),
  ('hgm', 'Hair Growth Mask', '125ml', 'Hair Growth', 110, null, 'RT-HGM', 'Infused with caffeine, biotin and Sheabutter to strengthen hair and reduce breakage. Repair, Rehydrate, Grow.', '/products/hair-growth-mask.png', true, 9),
  ('hgo', 'Hair Growth Oil', '50ml', 'Hair Growth', 85, null, 'RT-HGO', 'Watch your hair come back to life. This rich botanical blend supports fuller, healthier strands with lasting moisture and natural shine. Stimulates growth. The best pre-wash oil for keeps.', '/products/hair-growth-oil.png', true, 10),
  ('hgsh', 'Hair Growth Shampoo', '250ml', 'Hair Growth', 85, null, 'RT-HGSH', 'Our hair growth shampoo is enriched with natural ingredients to leave hair clean, silky, nourished and healthy.', '/products/hair-growth-shampoo.png', true, 11),
  ('hgt', 'Hair Growth Tonic', '50ml / 100ml', 'Hair Growth', 85, '[{"label":"50ml","price":85},{"label":"100ml","price":149}]'::jsonb, 'RT-HGT', 'Our revitalised Bay Rum tonic is a comprehensive, multi-action treatment designed to support optimal hair and scalp health. This invigorating blend of traditional botanicals and modern vitamins stimulates the scalp, nourishes the hair and leaves behind a classic, refreshing aroma. Infused with caffeine extract, saw palmetto and rosemary to block DHT and encourage hair growth.', '/products/hair-growth-tonic.jpg', true, 12),
  ('hmoist', 'Hair Moisturiser', '250ml', 'Hair Growth', 120, null, 'RT-HM', 'A rich, creamy leave-in moisturiser designed to deeply hydrate and soften hair without leaving it greasy or wet-looking. This lightweight formula melts effortlessly into the hair, delivering lasting moisture, smoothness and shine while keeping hair soft, fluffy and easy to manage.', '/products/hair-moisturiser.png', true, 13),
  ('hgser', 'Hairgrower Serum', '60ml', 'Hair Growth', 189, null, 'RT-HGSER', 'Designed to give you faster hair growth results. This serum is packed with tea tree oil, placenta, hyaluronic acid and 5% minoxidil.', '/products/hairgrower-serum.png', true, 14),
  ('hlser', 'Hairline Serum', '30ml', 'Hair Growth', 110, null, 'RT-HLSER', 'Topical solution 5% Minoxidil: it widens blood vessels and opens potassium channels, which increases blood flow and oxygen to hair follicles. It prolongs the growth (anagen) phase of your hair cycle, helping to revitalize shrunken follicles into thicker, healthier hair. Roll on your hairline once a day and massage well. For fast results, follow with your oil (castor oil or hairgrower oil) to avoid dryness.', '/products/hairline-serum.png', true, 15),
  ('hlt', 'Hairline Therapy', 'treatment', 'Hair Growth', 350, null, 'RT-HLT', 'Your hairline is exposed to all eyes in spaces you enter. This hairline therapy will help grow back your hairline and enhance your confidence! This set consists of Hairline Serum 10ml, Hair Tonic 50ml and Castor Oil 50ml / Extreme Hairgrower Oil 30ml.', '/products/hairline-therapy.png', true, 16),
  ('bbut', 'Beard Butter', '100g', 'King''s Care', 85, null, 'RT-KC-BB', 'Crafted with a blend of sheabutter and oils such as coconut oil, castor oil and rosemary. This beard butter will moisturise, strengthen and leave the shine on you.', '/products/beard-butter.jpg', true, 17),
  ('bgs', 'Beard Grower Serum', '30ml', 'King''s Care', 160, null, 'RT-KC-BGS', 'Starting off your grooming journey? Intending to have a healthy, fuller beard? This beard grower serum is designed to give you faster beard growth results. This oil is packed with tea tree oil, placenta, hyaluronic acid and 5% minoxidil.', '/products/beard-grower-serum.png', true, 18),
  ('beo', 'Beard Oil', '50ml', 'King''s Care', 120, null, 'RT-KC-BO', 'This lightweight, fast-absorbing blend is crafted to soften even the most stubborn whiskers while deeply hydrating the skin beneath. Infused with jojoba and argan oil, it eliminates ‘beard-ruff’ and itchiness, leaving your beard with a healthy, non-greasy shine and subtle, clean scent.', '/products/beard-oil.png', true, 19),
  ('kcond', 'Kids Conditioner', '250ml', 'Kids', 85, null, 'RT-KID-C', 'This gentle conditioner, designed for young hair, makes detangling a breeze. Infused with aloe vera, sheabutter and sweet almond oil. It deeply moisturises and nourishes, leaving hair soft, manageable and beautifully healthy. It also supports healthy hair growth for strong and vibrant locs.', '/products/kids-conditioner.png', true, 20),
  ('kmist', 'Kids Detangling Mist', '100ml', 'Kids', 85, null, 'RT-KID-DM', 'Specifically formulated for kids. This lightweight, leave-in spray combines the soothing hydration of aloe vera juice and cucumber extract with the nourishing benefits of grapeseed oil and vegetable keratin. It effortlessly detangles and softens, leaving hair silky, smooth and manageable. The sweet, buttery fragrance with light, candylike notes adds a touch of fun to every spritz.', '/products/kids-detangling-mist.png', true, 21),
  ('koil', 'Kids Hair Oil', '50ml', 'Kids', 85, null, 'RT-KID-O', 'Nourish and strengthen your child’s hair with our gentle growth oil. Infused with natural botanicals like hibiscus and fenugreek, plus a blend of enriching oils. It supports healthy hair growth and a happy scalp.', '/products/kids-hair-oil.png', true, 22),
  ('kmoist', 'Kids Moisturiser', '250ml', 'Kids', 120, null, 'RT-KID-M', 'A rich, creamy leave-in moisturiser designed to deeply hydrate and soften hair without leaving it greasy or wet-looking. This lightweight formula melts effortlessly into the hair, delivering lasting moisture, smoothness and shine while keeping hair soft, fluffy and easy to manage.', '/products/kids-moisturiser.png', true, 23),
  ('ksham', 'Kids Shampoo', '250ml', 'Kids', 85, null, 'RT-KID-S', 'This shampoo is specifically crafted for delicate young hair, using nature’s best. Hibiscus, aloe vera and sheabutter work together to gently cleanse, deeply moisturise and encourage healthy growth. A touch of refreshing cucumber extract adds a sweet, playful scent, complemented by subtle buttery and powdery notes for a comforting wash.', '/products/kids-shampoo.png', true, 24),
  ('rbc', 'Repairboost Conditioner', '250ml', 'Repairboost', 85, null, 'RT-RBC', 'Revive dry, damaged and chemically treated hair with this keratin and argan oil repair and shine conditioner. This deeply hydrating formula strengthens, repairs and restores shine. Infused with keratin, argan oil, hyaluronic acid and wheat protein. It leaves hair soft, silky and full of life.', '/products/repairboost-conditioner.png', true, 25),
  ('rbsh', 'Repairboost Shampoo', '250ml', 'Repairboost', 85, null, 'RT-RBSH', 'Revive dry, damaged and chemically treated hair with our crown restore shampoo. This deeply hydrating formula strengthens, repairs and restores shine. Infused with keratin, argan oil, hyaluronic acid and wheat protein. It leaves hair soft, silky and full of life.', '/products/repairboost-shampoo.png', true, 26),
  ('bco', 'Black Castor Oil', '100ml', 'Oils & Serums', 149, null, 'RT-BCO', 'Specifically formulated for wavy, curly and coily hair. It is ideal for thickening hair, reducing split ends, treating itchy scalps and providing a healthy sheen. Crafted to address hair concerns such as dryness, breakage, and lack of moisture retention.', '/products/black-castor-oil.jpg', true, 27),
  ('drm', 'Deep Repair Mask', '100ml', 'Oils & Serums', 85, null, 'RT-DRM', 'Deeply hydrate and restore dry and damaged hair with this luxurious mask. Enriched with 18 amino acids, hyaluronic acid, argan oil, keratin and aloe vera. It repairs strands for silky, soft and manageable results.', '/products/deep-repair-mask.png', true, 28),
  ('hps', 'Heat Protection Spray', '50ml', 'Oils & Serums', 85, null, 'RT-HPS', 'Protect your hair from heat damage while keeping it soft, smooth and full of shine. This lightweight, non-greasy mist forms a barrier against blow-dryers, flat-irons and curling tools, helping to reduce breakage, split ends and frizz.', '/products/heat-protection-spray.jpg', true, 29),
  ('shf', 'Sheabutter Hairfood', '125ml / 250ml', 'Oils & Serums', 120, '[{"label":"125ml","price":120},{"label":"250ml","price":189}]'::jsonb, 'RT-SHF', 'This rich, nourishing hair food is a daily treat for your hair and scalp. Crafted with a blend of natural butters and oils such as castor oil and rosemary. This hair food will moisturise, strengthen and protect hair from root to tip.', '/products/sheabutter-hairfood.jpg', true, 30)
